#include <cstdlib>
#include <exception>
#include <iostream>

int main() {
    std::set_terminate([]() {
        std::cout << "Unhandled exception\n" << std::flush;
        std::abort();
    });
    throw 1;
}

#include <iostream>
#include <thread>

void run() { throw std::runtime_error("Thread failure"); }

int main() {
    try {
        std::thread t{run};
        t.join();
        return EXIT_SUCCESS;
    } catch (const std::exception &ex) {
        std::cerr << "Exception: " << ex.what() << '\n';
    } catch (...) {
        std::cerr << "Unknown exception caught\n";
    }
    return EXIT_FAILURE;
}

#include <iostream>
#include <thread>

class foo {
  public:
    foo() { std::cerr << "foo::foo()\n"; }
    ~foo() { std::cerr << "foo::~foo()\n"; }
};

// Static object, expecting destructor on exit
foo f;

void run() { throw std::runtime_error("Thread failure"); }

int main() {
    std::set_terminate([]() {
        try {
            std::exception_ptr eptr{std::current_exception()};
            if (eptr) {
                std::rethrow_exception(eptr);
            } else {
                std::cerr << "Exiting without exception\n";
            }
        } catch (const std::exception &ex) {
            std::cerr << "Exception: " << ex.what() << '\n';
        } catch (...) {
            std::cerr << "Unknown exception caught\n";
        }
        std::exit(EXIT_FAILURE);
    });

    std::thread t{run};
    t.join();
}
